import AsyncStorage from '@react-native-async-storage/async-storage';

// enqueue an order for later processing
async function enqueueOrder(order) {
  const item = { id: order.id, type: 'order', payload: order, retryCount: 0, status: 'pending' };
  const qRaw = await AsyncStorage.getItem('orderOutbox');
  const queue = qRaw ? JSON.parse(qRaw) : [];
  queue.push(item);
  await AsyncStorage.setItem('orderOutbox', JSON.stringify(queue));
}

// process queue
async function processQueue() {
  const qRaw = await AsyncStorage.getItem('orderOutbox');
  const queue = qRaw ? JSON.parse(qRaw) : [];
  for (const it of queue.filter(i => i.status === 'pending')) {
    try {
      await api.placeOrder(it.payload, { idempotencyKey: it.id });
      it.status = 'completed';
    } catch (e) {
      it.retryCount = (it.retryCount || 0) + 1;
      // optional: computeBackoff(it.retryCount)
    }
  }
  await AsyncStorage.setItem('orderOutbox', JSON.stringify(queue));
}
``` 

